// Hand-written `@angular/router` stub: the shape of a route configuration, the
// router's navigations and a functional guard.

export interface Route {
  path?: string;
  pathMatch?: string;
  component?: unknown;
  loadComponent?: () => unknown;
  loadChildren?: () => unknown;
  children?: Route[];
  redirectTo?: string;
  providers?: unknown[];
  canActivate?: unknown[];
  data?: unknown;
  title?: string;
}

export type Routes = Route[];

export declare const RouterModule: {
  forRoot(routes: Routes): unknown;
  forChild(routes: Routes): unknown;
};

export declare function provideRouter(routes: Routes): unknown;
export declare const RouterLink: unknown;

export declare class UrlTree {
  toString(): string;
}

export declare class Router {
  navigate(commands: unknown[], extras?: unknown): Promise<boolean>;
  navigateByUrl(url: string): Promise<boolean>;
  createUrlTree(commands: unknown[]): UrlTree;
}
export declare const RouterOutlet: unknown;

export type CanActivateFn = (route: unknown, state: unknown) => boolean | UrlTree | Promise<boolean>;
